//! FIELDSET form content attributes preserve native ownership authority.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=fieldset form=owner><legend>Group</legend><input id=child value=seed></fieldset></form><form id=other></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://fieldset-form-attribute.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn fieldset_form_attribute_exact_public_and_null_namespace_owner_without_child_reassociation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),owner=document.getElementById('owner'),other=document.getElementById('other'),child=document.getElementById('child');owner.id='A\ud800z';other.id='A\udfffz';x.setAttribute('form','A\ud800z');var a=x.getAttributeNode('form');if(x.form!==owner||a.value!=='A\ud800z'||child.form!==owner)throw 'exact fieldset owner';x.setAttributeNS(null,'form','A\udfffz');if(x.form!==other||child.form!==owner||owner.length!==1||other.length!==1||a!==x.getAttributeNode('form')||a.value!=='A\udfffz')throw 'fieldset association never reassociates descendants';x.setAttribute('form','A\ufffdz');if(x.form!==null||child.form!==owner)throw 'scalar alias distinct';"#);}
#[test]
fn fieldset_form_attribute_attached_aliases_keep_identity_and_exact_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),owner=document.getElementById('owner'),other=document.getElementById('other'),a=x.getAttributeNode('form'),watch=new MutationObserver(function(){});owner.id='A\ud800z';other.id='A\udfffz';watch.observe(x,{attributes:true,attributeOldValue:true});a.value='A\ud800z';a.nodeValue='A\udfffz';a.textContent='A\ud800z';var records=watch.takeRecords();if(x.form!==owner||a!==x.getAttributeNode('form')||records.length!==3||records[0].oldValue!=='owner'||records[1].oldValue!=='A\ud800z'||records[2].oldValue!=='A\udfffz'||a.value!=='A\ud800z')throw 'actual attached form aliases';"#);}
#[test]
fn fieldset_form_attribute_conversion_and_canonical_owner_ignore_author_form(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),owner=document.getElementById('owner'),other=document.getElementById('other'),a=x.getAttributeNode('form'),get=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'form').get,calls=0;other.id='A\udfffz';Object.defineProperty(x,'form',{get:function(){throw 'author form';},configurable:true});x.setAttribute('form',{toString:function(){calls++;a.value='owner';return 'A\udfffz';}});if(calls!==1||get.call(x)!==other||a!==x.getAttributeNode('form')||a.value!=='A\udfffz'||document.getElementById('child').form!==owner)throw 'native form after conversion';"#);}

#[test]
fn fieldset_form_attribute_conversion_reentry_replaces_actual_attr_and_keeps_abrupt_effects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var fieldset=document.getElementById('fieldset'),old=fieldset.getAttributeNode('form'),calls=0;fieldset.setAttribute('form',{toString:function(){calls++;fieldset.removeAttribute('form');fieldset.setAttribute('form','callback');return 'A\ud800z';}});var actual=fieldset.getAttributeNode('form');if(calls!==1||actual===old||old.ownerElement!==null||old.value!=='owner'||actual.value!=='A\ud800z')throw 'conversion uses current actual attribute';var marker={},caught;try{fieldset.setAttribute('form',{toString:function(){fieldset.setAttribute('form','abrupt callback');throw marker;}});}catch(e){caught=e;}if(caught!==marker||fieldset.getAttribute('form')!=='abrupt callback'||fieldset.getAttributeNode('form')!==actual)throw 'abrupt conversion keeps completed author effects';caught=false;try{fieldset.setAttribute('form',Symbol('form'));}catch(e){caught=e instanceof TypeError;}if(!caught||actual.value!=='abrupt callback')throw 'symbol conversion refusal';"#);}

#[test]
fn fieldset_form_attribute_inert_clone_adoption_no_main_slots_and_whole_import_guard(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('fieldset');source.setAttribute('form','A\ud800z B\udfffz');var copy=source.cloneNode(true),a=copy.getAttributeNode('form'),target=document.implementation.createHTMLDocument('target');target.adoptNode(copy);target.body.appendChild(copy);if(copy.getAttribute('form')!==source.getAttribute('form')||a===source.getAttributeNode('form')||copy.ownerDocument!==target||a.ownerDocument!==target)throw 'independent clone and actual adopted attributes';source.setAttribute('form','fresh');if(a.value!=='A\ud800z B\udfffz')throw 'independent copied record';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();let error=p.runtime.execute("document.importNode(copy,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Import supports ordinary HTML containers"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();run(&mut d,&mut f,&mut p,r#"var isolated=owner.createElement('fieldset');isolated.setAttribute('form','X\ud800');var attr=isolated.getAttributeNode('form');attr.value='Y\udfff';if(isolated.getAttribute('form')!=='Y\udfff'||attr.ownerDocument!==owner||a.value!=='A\ud800z B\udfffz')throw 'fresh inert exact source without main slots';document.getElementById('fieldset').setAttribute('form','Z\ud800');"#);assert_eq!(d.nodes.len(),slots);}

#[test]
fn fieldset_form_attribute_qualified_foreign_and_other_element_guards_are_atomic(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var fieldset=document.getElementById('fieldset'),other=document.createElement('div'),shape=document.createElementNS('http://www.w3.org/2000/svg','svg');");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());for source in [r#"fieldset.setAttributeNS('urn:attribute','form','A\ud800');"#,r#"fieldset.setAttributeNS(null,'FORM','A\ud800');"#,r#"other.setAttribute('form','A\ud800');"#,r#"shape.setAttribute('form','A\ud800');"#]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{source}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}p.begin_job();run(&mut d,&mut f,&mut p,r#"fieldset.setAttribute('form','B\udfff');if(fieldset.getAttribute('form')!=='B\udfff')throw 'fresh exact native write recovery';"#);}

#[test]
fn fieldset_form_attribute_saved_child_origin_precedes_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var fieldset=document.getElementById('fieldset'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Function('node','value',"node.setAttribute('form',value);"),calls=0;saved(fieldset,'A\ud800z');"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-fieldset-for.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("saved(fieldset,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://fieldset-form-attribute.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,r#"if(calls||fieldset.getAttribute('form')!=='A\ud800z')throw 'origin before conversion';saved(fieldset,'B\udfffz');if(fieldset.getAttribute('form')!=='B\udfffz')throw 'fresh captured origin recovery';"#);}

#[test]
fn fieldset_form_attribute_null_namespace_writes_ignore_foreign_collision_after_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var fieldset=document.getElementById('fieldset');fieldset.setAttributeNS('urn:attribute','form','foreign');var foreign=fieldset.getAttributeNodeNS('urn:attribute','form'),a=fieldset.getAttributeNodeNS(null,'form'),calls=0;fieldset.setAttributeNS(null,'form',{toString:function(){calls++;fieldset.setAttributeNS(null,'form','callback');return 'A\ud800z';}});if(calls!==1||fieldset.getAttributeNodeNS(null,'form')!==a||a.value!=='A\ud800z'||foreign!==fieldset.getAttributeNodeNS('urn:attribute','form')||foreign.value!=='foreign'||fieldset.getAttributeNS(null,'form')!=='A\ud800z')throw 'exact converted null namespace fieldset attribute';"#);}

#[test]
fn fieldset_form_attribute_native_and_inert_writer_limits_preserve_records_and_recover(){for inert in [false,true]{for source in [r#"fieldset.setAttribute('form','long A\ud800z B\udfffz');"#,r#"fieldset.setAttributeNS(null,'form','long A\ud800z B\udfffz');"#,r#"attr.value='long A\ud800z B\udfffz';"#,r#"attr.nodeValue='long A\ud800z B\udfffz';"#,r#"attr.textContent='long A\ud800z B\udfffz';"#]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=document.implementation.createHTMLDocument('inert'),fieldset=doc.createElement('fieldset');fieldset.setAttribute('form','owner');var attr=fieldset.getAttributeNode('form'),watch=new MutationObserver(function(){});watch.observe(fieldset,{attributes:true,attributeOldValue:true});"}else{"var fieldset=document.getElementById('fieldset'),attr=fieldset.getAttributeNode('form'),watch=new MutationObserver(function(){});watch.observe(fieldset,{attributes:true,attributeOldValue:true});"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='owner'||fieldset.getAttributeNode('form')!==attr||watch.takeRecords().length)throw 'atomic form writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r#"var records=watch.takeRecords();if(attr.value!=='long A\ud800z B\udfffz'||fieldset.getAttributeNode('form')!==attr||records.length!==1||records[0].oldValue!=='owner'||records[0].attributeName!=='form'||records[0].attributeNamespace!==null||fieldset.form!==null)throw 'fresh writer recovery';"#);}}}}
#[test]
fn fieldset_form_attribute_html_casefold_and_widget_reassociation_boundary(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var fieldset=document.getElementById('fieldset'),other=document.getElementById('other'),owner=document.getElementById('owner');fieldset.setAttribute('FORM','other');if(fieldset.form!==other||fieldset.getAttribute('form')!=='other'||fieldset.getAttributeNodeNS(null,'FORM')!==null)throw 'HTML name normalization';var field=document.createElement('input');owner.appendChild(field);field.value='keep';");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text())).collect::<Vec<_>>();p.begin_job();let error=p.runtime.execute("field.setAttribute('form','other');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("exclude"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text())).collect::<Vec<_>>(),controls);p.begin_job();run(&mut d,&mut f,&mut p,"if(field.form!==owner||field.value!=='keep'||fieldset.form!==other)throw 'widget authority preserved';fieldset.setAttribute('form','owner');if(fieldset.form!==owner)throw 'fresh passive owner recovery';");}

#[test]
fn fieldset_form_attribute_native_reset_retains_descendant_owner_and_ignores_form_shadow(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("owner")).unwrap();let other=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("other")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('fieldset'),owner=document.getElementById('owner'),other=document.getElementById('other'),child=document.getElementById('child'),get=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'form').get;child.value='edited';Object.defineProperty(x,'form',{value:owner,configurable:true});x.setAttribute('form','other');if(get.call(x)!==other||child.form!==owner||x.form!==owner||owner.length!==1||other.length!==1)throw 'actual fieldset and descendant owners';");p.begin_job();reset_form(&mut d,&mut f,Some(&mut p),other).unwrap();run(&mut d,&mut f,&mut p,"if(child.value!=='edited')throw 'fieldset owner never forwards reset';");p.begin_job();reset_form(&mut d,&mut f,Some(&mut p),owner).unwrap();run(&mut d,&mut f,&mut p,"if(child.value!=='seed')throw 'actual child owner reset';delete x.form;x.removeAttribute('form');if(x.form!==owner||child.form!==owner||owner.length!==2||other.length!==0)throw 'ancestor owner recovery';");}
